mapper.select:
SELECT 
  FROM workflow_definitions w
 WHERE w.tenant_id = #{tenantId}

   AND w.entity_type = #{entityType}


   AND w.active_yn = TRUE

 ORDER BY w.entity_type, w.workflow_code

SELECT workflow_id, tenant_id, workflow_code, workflow_name, description, entity_type, initial_state_code, active_yn, is_template, parent_workflow_id, template_version FROM workflow_definitions WHERE workflow_code = #{workflowCode}
AND tenant_id = #{tenantId}
AND tenant_id IS NULL
LIMIT 1

mapper.delete:
DELETE FROM workflow_definitions
 WHERE workflow_id = #{workflowId}
 AND (tenant_id = #{tenantId} OR tenant_id IS NULL)

mapper.select:
SELECT * FROM workflow_transitions
 WHERE workflow_id = #{workflowId}
 ORDER BY sort_order, transition_id
